   [107]={next_id=108, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="外界的目光很快投来了这里，恰巧在这个时候，黑市上又传出一个消息：某个实验品杀死了所有的守卫和试验人员逃了出来，随后消失在了漫漫黄沙中。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_403.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
